<?php declare(strict_types=1); final class SavedItem extends Model { public function toggleJob(int $uid,int $job): void { $s=$this->db->prepare('SELECT id FROM saved_jobs WHERE freelancer_id=:u AND job_id=:j');$s->execute(['u'=>$uid,'j'=>$job]);if($s->fetch()){$this->db->prepare('DELETE FROM saved_jobs WHERE freelancer_id=:u AND job_id=:j')->execute(['u'=>$uid,'j'=>$job]);}else{$this->db->prepare('INSERT INTO saved_jobs(freelancer_id,job_id) VALUES(:u,:j)')->execute(['u'=>$uid,'j'=>$job]);} } public function toggleFreelancer(int $eid,int $fid): void { $s=$this->db->prepare('SELECT id FROM saved_freelancers WHERE employer_id=:e AND freelancer_id=:f');$s->execute(['e'=>$eid,'f'=>$fid]);if($s->fetch()){$this->db->prepare('DELETE FROM saved_freelancers WHERE employer_id=:e AND freelancer_id=:f')->execute(['e'=>$eid,'f'=>$fid]);}else{$this->db->prepare('INSERT INTO saved_freelancers(employer_id,freelancer_id) VALUES(:e,:f)')->execute(['e'=>$eid,'f'=>$fid]);} } public function jobs(int $uid): array { $s=$this->db->prepare('SELECT j.*,p.display_name AS employer_name FROM saved_jobs s JOIN jobs j ON j.id=s.job_id LEFT JOIN profiles p ON p.user_id=j.employer_id WHERE s.freelancer_id=:u ORDER BY s.created_at DESC');$s->execute(['u'=>$uid]);return $s->fetchAll(); } public function freelancers(int $uid): array { $s=$this->db->prepare('SELECT p.* FROM saved_freelancers s JOIN profiles p ON p.user_id=s.freelancer_id WHERE s.employer_id=:u ORDER BY s.created_at DESC');$s->execute(['u'=>$uid]);return $s->fetchAll(); } }